CREATE TABLE IF NOT EXISTS "bookings_config" (
  "id" SERIAL,
  "title" varchar(255) NOT NULL default '',
  "num_months" INTEGER NOT NULL default '3',
  "default_lang" varchar(6) NOT NULL default 'en',
  "theme" varchar(50) NOT NULL default 'default',
  "start_day" TEXT CHECK ("start_day" IN ('mon','sun')) NOT NULL default 'sun',
  "date_format" TEXT CHECK ("date_format" IN ('us','eu')) NOT NULL default 'eu',
  "click_past_dates" TEXT CHECK ("click_past_dates" IN ('on','off')) NOT NULL default 'off',
  "cal_url" varchar(255) NOT NULL default '',
  "local_path" varchar(255) NOT NULL default '/calendar',
  "version" varchar(10) NOT NULL DEFAULT '',
  PRIMARY KEY  ("id")
);

